function negotiate(accept, available) {
  if (!accept) return available[0] || null;
  const ranges = accept.split(',').map((part) => {
    const [type, ...params] = part.trim().split(';');
    let q = 1;
    for (const p of params) {
      const [k, v] = p.trim().split('=');
      if (k === 'q') q = Number(v);
    }
    return { type: type.trim().toLowerCase(), q };
  });
  const quality = (t) => {
    const [major] = t.split('/');
    let q = 0;
    let specificity = -1;
    for (const r of ranges) {
      let s = -1;
      if (r.type === t) s = 2;
      else if (r.type === major + '/*') s = 1;
      else if (r.type === '*/*') s = 0;
      if (s > specificity) { specificity = s; q = r.q; }
    }
    return q;
  };
  let pick = null;
  let best = 0;
  for (const t of available) {
    const q = quality(t);
    if (q > best) { pick = t; best = q; }
  }
  return pick;
}

