  let i = 0;
  function next(err) {
    while (i < stack.length) {
      const mw = stack[i++];
      const isErrorHandler = mw.length === 4;
      if (Boolean(err) !== isErrorHandler) continue;
      try {
        return err ? mw(err, req, res, next) : mw(req, res, next);
      } catch (thrown) {
        return next(thrown);
      }
    }
  }
  next();
}

