function sanitize(input) {
  let removed = 0;
  const walk = (v) => {
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === 'object') {
      const out = {};
      for (const [k, val] of Object.entries(v)) {
        if (k.startsWith('$') || k.includes('.')) { removed++; continue; }
        out[k] = walk(val);
      }
      return out;
    }
    return v;
  };
  const clean = walk(input);
  return { clean, removed };
}

