function joinPath(...parts) {
  const p = parts.join('/').replace(/\/+/g, '/');
  if (p === '' || p === '/') return '/';
  return p.endsWith('/') ? p.slice(0, -1) : p;
}

function flattenRoutes(node, base = '') {
  const prefix = joinPath(base, node.prefix);
  const out = (node.routes || []).map((r) => r.method + ' ' + joinPath(prefix, r.path));
  for (const child of node.children || []) out.push(...flattenRoutes(child, prefix));
  return out;
}

